/**
 * The inline R helper definitions the exporter can emit, keyed by the name a
 * mark requests one by. A script carries only the helpers it references, so a
 * reader gets plain rtracklayer and ggplot2 they can edit in place.
 */
export const HELPERS: Record<string, string> = {
  read_bigwig: "# Read a BigWig region into a data.frame(seqnames, start, end, score). start is\n# 0-based half-open (BED-style), like every other reader here - rtracklayer hands\n# back 1-based inclusive GRanges coordinates, so the start is shifted back by one.\n# That conversion is what makes adjacent bins ABUT: a bigwig's bins tile the\n# genome, and left as 1-based each bar was drawn one bp right of its true span\n# with a 1bp hole against its neighbour. Sub-pixel at any normal zoom, but the\n# device antialiases each rect separately, so the holes beat against the pixel\n# grid and surfaced as scattered full-height white seams through a solid xyplot.\nread_bigwig <- function(uri, chrom, start, end) {\n  df <- as.data.frame(rtracklayer::import(uri, which = GRanges(chrom, IRanges(start + 1, end))))\n  df$start <- df$start - 1L\n  df\n}",
  read_gff: "# Read GFF3 features in a region into a\n# data.frame(start, end, strand, type, id, parent, name), plus one column per\n# name in 'attrs' - the extra GFF attributes the track's feature filters read\n# (e.g. gbkey for the NCBI source-record filter every track carries by default).\n# An attribute the file does not have becomes an all-NA column, which is the\n# jexl `undefined` feature_filter() already handles.\nread_gff <- function(uri, chrom, start, end, attrs = character(0)) {\n  g <- import(uri, which = GRanges(chrom, IRanges(start + 1, end)), format = \"gff\")\n  m <- mcols(g)\n  # length(g), not a bare NA: recycling a length-1 NA works only when there is\n  # at least one feature, so an empty region over a file lacking the attribute\n  # died on \"arguments imply differing number of rows: 0, 1\"\n  # A GFF attribute can hold a comma list, which rtracklayer surfaces as a\n  # CharacterList - and as.character() on one ERRORS (\"coercing an AtomicList\n  # object to an atomic vector is supported only for objects with top-level\n  # elements of length <= 1\") rather than flattening, so join it back to the\n  # spelling the file used. Only single-valued attributes went through before.\n  col <- function(nm) {\n    v <- m[[nm]]\n    if (is.null(v)) rep(NA_character_, length(g))\n    else if (methods::is(v, \"List\")) vapply(v, function(x)\n      if (length(x)) paste(as.character(x), collapse = \",\") else NA_character_,\n      character(1))\n    else as.character(v)\n  }\n  parent <- if (is.null(m$Parent)) rep(NA_character_, length(g)) else\n    vapply(m$Parent, function(v) if (length(v)) as.character(v[[1]]) else NA_character_, character(1))\n  df <- data.frame(start = start(g) - 1L, end = end(g), strand = as.character(strand(g)),\n             type = col(\"type\"), id = col(\"ID\"), parent = parent, name = col(\"Name\"),\n             stringsAsFactors = FALSE)\n  for (a in attrs) df[[a]] <- col(a)\n  df\n}",
  read_regions: "# Read one data.frame per region with reader(chrom, start, end), clip each\n# feature to its region (JBrowse cuts features at the region edge) and shift the\n# named coordinate columns onto the cumulative-bp axis region_layout() defines,\n# then rbind into one long frame with a '.region' column. This lets a single\n# ggplot panel span several discontiguous regions on one x-axis. 'reader' returns\n# a genomic-coordinate data.frame; 'coords' names its coordinate columns to\n# clip+shift (point columns are already within range, so clipping is a no-op). A\n# NULL/empty read contributes nothing; an all-empty result keeps the columns.\n# clip = FALSE only shifts (for geometry that must keep its shape at the edges,\n# e.g. Hi-C diamond vertices), otherwise coordinates are clipped to the region.\nread_regions <- function(reader, regions, coords, clip = TRUE) {\n  parts <- lapply(seq_len(nrow(regions)), function(i) {\n    df <- reader(regions$chrom[i], regions$start[i], regions$end[i])\n    if (is.null(df) || !nrow(df)) return(NULL)\n    shift <- regions$offset[i] - regions$start[i]\n    for (col in coords) {\n      v <- df[[col]]\n      if (clip) v <- pmin(pmax(v, regions$start[i]), regions$end[i])\n      df[[col]] <- v + shift\n    }\n    df$.region <- i\n    df\n  })\n  out <- do.call(rbind, parts)\n  if (is.null(out)) {\n    out <- reader(regions$chrom[1], regions$start[1], regions$start[1])\n    out$.region <- integer(0)\n  }\n  out\n}",
  read_vcf: "# Read VCF records in a region via the tabix index (Rsamtools - no\n# VariantAnnotation needed) into data.frame(start, end, ref, alt, type). SV span\n# (END) and SVTYPE come from the INFO column; sequence indels are classed by\n# REF/ALT length. start is 0-based half-open (BED-style).\nread_vcf <- function(uri, chrom, start, end) {\n  info_field <- function(info, key) {\n    pat <- paste0(\"(?:^|;)\", key, \"=([^;]*)\")\n    vapply(info, function(x) {\n      r <- regmatches(x, regexpr(pat, x, perl = TRUE))\n      if (length(r)) sub(pat, \"\\\\1\", r, perl = TRUE) else NA_character_\n    }, character(1), USE.NAMES = FALSE)\n  }\n  lines <- unlist(scanTabix(TabixFile(uri),\n    param = GRanges(chrom, IRanges(start + 1, end))))\n  cols <- if (length(lines)) do.call(rbind, strsplit(lines, \"\\t\", fixed = TRUE))\n          else matrix(character(), 0, 8)\n  pos <- as.integer(cols[, 2]); ref <- cols[, 4]\n  alt <- sub(\",.*\", \"\", cols[, 5]); info <- cols[, 8]\n  symbolic <- grepl(\"^<\", alt)\n  end_info <- suppressWarnings(as.integer(info_field(info, \"END\")))\n  svtype <- info_field(info, \"SVTYPE\")\n  type <- ifelse(symbolic,\n      ifelse(!is.na(svtype), svtype, gsub(\"[<>]\", \"\", alt)),\n    ifelse(nchar(ref) == 1 & nchar(alt) == 1, \"SNV\",\n      ifelse(nchar(ref) < nchar(alt), \"INS\",\n        ifelse(nchar(ref) > nchar(alt), \"DEL\", \"MNV\"))))\n  data.frame(start = pos - 1L,\n             end = ifelse(symbolic & !is.na(end_info), end_info, pos + nchar(ref) - 1L),\n             ref = ref, alt = alt, type = type, stringsAsFactors = FALSE)\n}",
  region_layout: "# Lay a set of displayed regions out on one continuous \"cumulative bp\" x-axis,\n# the way JBrowse concatenates several regions in a single linear view: each\n# region occupies a span proportional to its bp width, with a small gap between\n# them. 'regions' is a data.frame(chrom, start, end) (0-based half-open); this\n# adds offset (the region's left edge on the cumulative axis), width, gap, and\n# cum_start/cum_end. The first region is anchored at its own genomic start, so a\n# lone region keeps native genomic coordinates (a single-region figure is\n# unchanged). cum_pos for a position p in region i is offset[i] + (p - start[i]).\nregion_layout <- function(regions, gap_frac = 0.012) {\n  w <- regions$end - regions$start\n  gap <- max(1, round(sum(w) * gap_frac))\n  regions$offset <- regions$start[1] + head(cumsum(c(0, w + gap)), length(w))\n  regions$width <- w; regions$gap <- gap\n  regions$cum_start <- regions$offset; regions$cum_end <- regions$offset + w\n  regions\n}",
}
